using System;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using SplifyWin;
namespace Mcrf.Wpf {public sealed partial class MainWindow {
 UIElement CompactAutoSelectionRow(){
  var row=new Grid{Margin=new Thickness(8,4,8,4),MinHeight=48};foreach(var width in new[]{36d,-1d,72d,40d,88d})row.ColumnDefinitions.Add(new ColumnDefinition{Width=width<0?new GridLength(1,GridUnitType.Star):new GridLength(width)});
  var help=Button("i",()=>{var window=Dialog("Автовыбор",440,540);var panel=new DockPanel{Margin=new Thickness(16)};var close=Button("Понятно",()=>window.Close());DockPanel.SetDock(close,Dock.Bottom);panel.Children.Add(close);panel.Children.Add(new ScrollViewer{Content=Text("Два независимых интервала\n\n«Автоопределение БС» задаёт частоту проверки ограничений сети для перехода VPN ↔ БС. Его включение не меняет интервал автовыбора сервера.\n\n«Автовыбор» задаёт частоту проверки серверов внутри текущего раздела. Его интервал не включает автоопределение БС и не меняет частоту проверки ограничений.\n\nВыбор сервера\n\nВыкл — ручной выбор. Самый быстрый — доступный сервер с минимальной задержкой. Последний выбранный — приоритет последнего выбранного сервера.\n\nОтклонение\n\nМинимальный выигрыш по задержке для смены рабочего сервера: 15–150 мс. Малое отклонение может вызывать частые переключения и мешать видео, музыке и длительным соединениям.\n\n«При недоступности»: рабочий сервер сохраняется независимо от разницы пинга; замена выполняется после неудачной проверки доступности.",12),VerticalScrollBarVisibility=ScrollBarVisibility.Auto});window.Content=panel;window.ShowDialog();});help.Name="compactAutoHelp";help.ToolTip="Справка об автовыборе";help.Style=(Style)FindResource("CompactIconAction");help.Content=CompactIcon("info",18);help.MinWidth=0;help.Width=30;help.Height=30;help.MinHeight=30;help.Padding=new Thickness(6);help.Margin=new Thickness(0);row.Children.Add(help);
  var title=new TextBlock{Text="Автовыбор",FontSize=12,Foreground=Brush(CompactPrimary),VerticalAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Center};Grid.SetColumn(title,1);row.Children.Add(title);
  var intervals=CompactCadenceValues(session.State.AutoSelectIntervalSeconds,5);var cadence=new ComboBox{Name="compactAutoInterval",ItemsSource=intervals.Select(CompactCadenceLabel).ToArray(),MinWidth=0,FontSize=10,Padding=new Thickness(3),Margin=new Thickness(2,0,2,0),VerticalAlignment=VerticalAlignment.Center,ToolTip="Интервал автовыбора сервера"};Grid.SetColumn(cadence,2);row.Children.Add(cadence);
  var policy=Button("",()=>{});policy.Name="compactAutoPolicy";policy.MinWidth=0;policy.Margin=new Thickness(2,0,2,0);policy.Padding=new Thickness(2);policy.FontSize=16;policy.Style=(Style)FindResource("IconAction");policy.Height=32;policy.MinHeight=32;Grid.SetColumn(policy,3);row.Children.Add(policy);
  var tolerances=Enumerable.Range(1,10).Select(x=>x*15).Concat(new[]{session.State.AutoSelectToleranceMs}).Where(x=>x>=0).Distinct().OrderBy(x=>x).ToArray();var deviation=new ComboBox{Name="compactAutoDeviation",ItemsSource=new[]{"При недоступности"}.Concat(tolerances.Select(x=>x+" мс")).ToArray(),MinWidth=0,FontSize=10,Padding=new Thickness(3),Margin=new Thickness(2,0,0,0),VerticalAlignment=VerticalAlignment.Center,ToolTip="Отклонение задержки"};Grid.SetColumn(deviation,4);row.Children.Add(deviation);
  bool syncing=false;Action sync=()=>{syncing=true;try{cadence.SelectedIndex=Math.Max(0,Array.IndexOf(intervals,session.State.AutoSelectIntervalSeconds));deviation.SelectedIndex=session.State.AutoSelectFailureOnly?0:Math.Max(1,Array.IndexOf(tolerances,session.State.AutoSelectToleranceMs)+1);policy.Content=CompactIcon(!session.State.AutoSelect?"connect":session.State.AutoSelectMode=="recent"?"refresh":"ping",18);policy.ToolTip=!session.State.AutoSelect?"Выбор сервера: выключен":session.State.AutoSelectMode=="recent"?"Последний выбранный":"Самый быстрый";}finally{syncing=false;}};
  Func<Action,Task> save=async action=>{if(busy||closing||closeRequested){sync();return;}row.IsEnabled=false;try{await Run(()=>session.ChangeConfiguration(()=>{action();session.State.AutoSelectSettingsVersion=1;}),sync);}finally{row.IsEnabled=true;sync();}};
  var menu=new ContextMenu();foreach(var key in new[]{"off","fast","recent"}){string mode=key;var item=new MenuItem{Header=key=="off"?"Выкл":key=="fast"?"Самый быстрый":"Последний выбранный"};item.Click+=async(s,e)=>await save(()=>{session.State.AutoSelect=mode!="off";if(mode!="off")session.State.AutoSelectMode=mode;});menu.Items.Add(item);}policy.ContextMenu=menu;policy.Click+=(s,e)=>{menu.PlacementTarget=policy;menu.IsOpen=true;};cadence.SelectionChanged+=async(s,e)=>{if(syncing||cadence.SelectedIndex<0)return;int seconds=intervals[cadence.SelectedIndex];await save(()=>session.State.AutoSelectIntervalSeconds=seconds);};deviation.SelectionChanged+=async(s,e)=>{if(syncing||deviation.SelectedIndex<0)return;int index=deviation.SelectedIndex;await save(()=>{session.State.AutoSelectFailureOnly=index==0;if(index>0)session.State.AutoSelectToleranceMs=tolerances[index-1];});};sync();
  var card=new Border{Name="compactAutoSelectCard",Child=row,Margin=new Thickness(0,0,0,10),Tag=sync};StyleCompactCard(card);return card;
 }
}}
